//! Process bootstrap: logging, async runtime, renderer selection, main window.

use anyhow::Context;
use slint::ComponentHandle;
use std::time::{Duration, Instant};

// Code generated by Slint from `ui/*.slint`; not ours to hold to the no-unwrap rule.
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
mod generated {
    slint::include_modules!();
}
pub use generated::*;

use crate::backend::Backend;

/// A failure this early means the renderer could not drive the window at all.
const RENDERER_STARTUP_WINDOW: Duration = Duration::from_secs(5);
/// A renderer that has not drawn its first frame by then counts as failed.
const FIRST_FRAME_TIMEOUT: Duration = Duration::from_secs(6);

/// The renderer was selected and the window shown, but nothing was ever drawn
/// (Skia creates its GPU surface lazily, so a missing driver surfaces here).
#[derive(Debug)]
struct NoFirstFrame;

impl std::fmt::Display for NoFirstFrame {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "the renderer drew no frame within {FIRST_FRAME_TIMEOUT:?}"
        )
    }
}

impl std::error::Error for NoFirstFrame {}
const INDEX_ENV: &str = "SLATE_RENDERER_INDEX";

#[derive(Clone, Copy, Debug)]
enum Renderer {
    #[cfg(target_os = "linux")]
    SkiaVulkan,
    /// Skia's platform default; Direct3D on Windows.
    #[cfg(windows)]
    SkiaD3d,
    SkiaOpenGl,
    FemtoVg,
    Software,
}

impl Renderer {
    const fn name(self) -> &'static str {
        match self {
            #[cfg(target_os = "linux")]
            Self::SkiaVulkan => "skia-vulkan",
            #[cfg(windows)]
            Self::SkiaD3d => "skia-d3d",
            Self::SkiaOpenGl => "skia-opengl",
            Self::FemtoVg => "femtovg",
            Self::Software => "software",
        }
    }

    fn select(self) -> Result<(), slint::PlatformError> {
        let sel = slint::BackendSelector::new().backend_name("winit".into());
        match self {
            #[cfg(target_os = "linux")]
            Self::SkiaVulkan => sel.renderer_name("skia".into()).require_vulkan(),
            #[cfg(windows)]
            Self::SkiaD3d => sel.renderer_name("skia".into()),
            Self::SkiaOpenGl => sel.renderer_name("skia-opengl".into()),
            Self::FemtoVg => sel.renderer_name("femtovg".into()),
            Self::Software => sel.renderer_name("software".into()),
        }
        .select()
    }
}

/// Default → most compatible. Which entries exist depends on Cargo features.
const CHAIN: &[Renderer] = &[
    #[cfg(all(feature = "renderer-skia-vulkan", target_os = "linux"))]
    Renderer::SkiaVulkan,
    #[cfg(all(feature = "renderer-skia", windows))]
    Renderer::SkiaD3d,
    #[cfg(feature = "renderer-skia")]
    Renderer::SkiaOpenGl,
    #[cfg(feature = "renderer-femtovg")]
    Renderer::FemtoVg,
    #[cfg(feature = "renderer-software")]
    Renderer::Software,
];

pub fn run(
    incoming: Option<std::sync::mpsc::Receiver<String>>,
    link: Option<String>,
) -> anyhow::Result<()> {
    let _log_guard = init_tracing();

    // `SLINT_BACKEND` wins: hand the decision to Slint untouched.
    let forced = std::env::var("SLINT_BACKEND").ok();
    let index: usize = std::env::var(INDEX_ENV)
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or_else(|| remembered_index(forced.is_some()));

    // Skia creates its Vulkan surface lazily, after `launch` has already
    // reported success, so a missing driver would leave an invisible window
    // instead of failing over. Skip Vulkan up front when it cannot work.
    #[cfg(all(feature = "renderer-skia-vulkan", target_os = "linux"))]
    let index = if forced.is_none()
        && matches!(CHAIN.get(index), Some(Renderer::SkiaVulkan))
        && !vulkan_usable()
    {
        tracing::warn!("no usable Vulkan device; skipping the Skia/Vulkan renderer");
        index + 1
    } else {
        index
    };

    #[cfg(all(windows, feature = "renderer-software"))]
    let index = match CHAIN.iter().position(|r| matches!(r, Renderer::Software)) {
        Some(sw) if forced.is_none() && index < sw && !hardware_gpu_present() => {
            tracing::warn!("no hardware GPU adapter; using the software renderer");
            sw
        }
        _ => index,
    };

    // A fallback child gets later launches' messages from its parent, which
    // keeps the single-instance socket, over stdin (see `respawn`).
    let incoming = incoming.or_else(|| {
        std::env::var_os(INDEX_ENV)
            .is_some()
            .then(stdin_messages)
            .flatten()
    });
    let inbox = incoming.map(Inbox::start);

    let started = Instant::now();
    let outcome = launch(forced.as_deref(), index, inbox.clone(), link);

    match outcome {
        Err(e)
            if forced.is_none()
                && (started.elapsed() < RENDERER_STARTUP_WINDOW
                    || e.downcast_ref::<NoFirstFrame>().is_some()) =>
        {
            // The failed window is gone; hold messages until the child attaches.
            if let Some(inbox) = &inbox {
                inbox.detach();
            }
            match CHAIN.get(index + 1) {
                Some(next) => {
                    tracing::warn!(
                        failed = CHAIN.get(index).map_or("?", |r| r.name()),
                        next = next.name(),
                        error = %format!("{e:#}"),
                        "renderer failed during startup; retrying with the next one"
                    );
                    respawn(index + 1, inbox.as_ref())
                }
                None => Err(e.context("every renderer failed to start")),
            }
        }
        other => other,
    }
}

/// Where to start the renderer chain: the renderer a previous fallback ended
/// on, if any, so a machine whose GPU path fails does not wait through the
/// failing renderers on every launch.
fn remembered_index(forced: bool) -> usize {
    if forced {
        return 0;
    }
    let prefs = crate::uiprefs::UiPrefs::load();
    let position = |name: &str| CHAIN.iter().position(|r| r.name() == name);
    // A renderer that never got confirmed took the whole process down (an
    // access violation in a GPU driver cannot be caught): start after it.
    if let Some(crashed) = prefs.renderer_pending.as_deref().and_then(position) {
        tracing::warn!(
            renderer = CHAIN.get(crashed).map_or("?", |r| r.name()),
            "this renderer crashed during the last startup; skipping it"
        );
        // Nothing after it: start over rather than run off the chain.
        return if crashed + 1 < CHAIN.len() {
            crashed + 1
        } else {
            0
        };
    }
    prefs.renderer.as_deref().and_then(position).unwrap_or(0)
}

fn update_prefs(f: impl FnOnce(&mut crate::uiprefs::UiPrefs)) {
    let mut prefs = crate::uiprefs::UiPrefs::load();
    let before = prefs.clone();
    f(&mut prefs);
    if prefs != before {
        if let Err(e) = prefs.save() {
            tracing::warn!("could not save renderer state: {e}");
        }
    }
}

/// Marks `name` as being tried; cleared by [`confirm_renderer`] or a clean exit.
fn mark_renderer_pending(name: &'static str) {
    update_prefs(|p| p.renderer_pending = Some(name.to_string()));
}

fn clear_renderer_pending() {
    update_prefs(|p| p.renderer_pending = None);
}

/// Once the renderer has drawn for a while it is confirmed. If it was reached
/// by falling back (or by skipping a crashed one), remember it for next time.
fn confirm_renderer(
    name: &'static str,
    index: usize,
    no_frame: std::rc::Rc<std::cell::Cell<bool>>,
) {
    slint::Timer::single_shot(FIRST_FRAME_TIMEOUT + Duration::from_secs(1), move || {
        if no_frame.get() {
            return;
        }
        update_prefs(|p| {
            p.renderer_pending = None;
            if index > 0 && p.renderer.as_deref() != Some(name) {
                tracing::info!(renderer = name, "remembered the working renderer");
                p.renderer = Some(name.to_string());
            }
        });
    });
}

/// True when DXGI reports a hardware adapter. Without one (VMs, remote
/// sessions, CI runners on the Basic Render Driver) Skia/D3D and OpenGL crash
/// the process with an access violation instead of failing, so the software
/// renderer is the only safe choice.
#[cfg(windows)]
fn hardware_gpu_present() -> bool {
    use windows::Win32::Graphics::Dxgi::{
        CreateDXGIFactory1, IDXGIFactory1, DXGI_ADAPTER_FLAG_SOFTWARE,
    };
    // SAFETY: DXGI COM calls on interfaces created here and released on drop.
    unsafe {
        let Ok(factory) = CreateDXGIFactory1::<IDXGIFactory1>() else {
            return true; // cannot tell; do not block the GPU renderers
        };
        let mut i = 0;
        while let Ok(adapter) = factory.EnumAdapters1(i) {
            i += 1;
            let Ok(desc) = adapter.GetDesc1() else {
                continue;
            };
            let software = desc.Flags & DXGI_ADAPTER_FLAG_SOFTWARE.0 as u32 != 0;
            // Microsoft Basic Render Driver (WARP).
            let basic = desc.VendorId == 0x1414 && desc.DeviceId == 0x8c;
            if !software && !basic {
                return true;
            }
        }
        false
    }
}

/// True when the Vulkan loader is present, an instance can be created and it
/// reports at least one physical device.
#[cfg(all(feature = "renderer-skia-vulkan", target_os = "linux"))]
fn vulkan_usable() -> bool {
    use ash::vk;
    // SAFETY: `Entry::load` dlopens the system Vulkan loader; the instance is
    // created from valid, fully initialised structs and destroyed before
    // return, and nothing derived from it outlives this function.
    unsafe {
        let Ok(entry) = ash::Entry::load() else {
            return false;
        };
        let app = vk::ApplicationInfo::default().api_version(vk::API_VERSION_1_1);
        let info = vk::InstanceCreateInfo::default().application_info(&app);
        let Ok(instance) = entry.create_instance(&info, None) else {
            return false;
        };
        let usable = instance
            .enumerate_physical_devices()
            .is_ok_and(|d| !d.is_empty());
        instance.destroy_instance(None);
        usable
    }
}

fn launch(
    forced: Option<&str>,
    index: usize,
    inbox: Option<Inbox>,
    link: Option<String>,
) -> anyhow::Result<()> {
    let mut chosen = None;
    let active = match forced {
        Some(name) => {
            tracing::info!(backend = name, "SLINT_BACKEND override in effect");
            // Initialise the platform now (it honours SLINT_BACKEND) so the
            // app id below applies, as it does on the chosen-renderer path.
            slint::BackendSelector::new()
                .select()
                .map_err(|e| anyhow::anyhow!("SLINT_BACKEND={name}: {e}"))?;
            name.to_string()
        }
        None => {
            let renderer = *CHAIN.get(index).context("no renderer compiled in")?;
            renderer
                .select()
                .map_err(|e| anyhow::anyhow!("selecting {}: {e}", renderer.name()))?;
            chosen = Some(renderer);
            mark_renderer_pending(renderer.name());
            renderer.name().to_string()
        }
    };

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .thread_name("slate-rt")
        .build()
        .context("starting tokio runtime")?;
    let _guard = runtime.enter();

    // Wayland app_id / X11 WM_CLASS: matches `slate.desktop` (StartupWMClass),
    // so docks and taskbars show the right icon and group the window.
    if let Err(e) = slint::set_xdg_app_id("slate") {
        tracing::debug!("could not set the app id: {e}");
    }
    let window = AppWindow::new().context("creating main window")?;
    window.show().context("showing main window")?;
    tracing::info!(renderer = %active, "UI renderer active");

    let initial_theme = crate::themes::load_saved();
    crate::themes::apply(&window, &initial_theme);
    let backend = Backend::start(runtime.handle().clone(), &window, initial_theme);
    wire(&window, &backend);
    if let Some(l) = link {
        backend.queue_link(l);
    }
    if let Some(inbox) = &inbox {
        // Messages from later launches: raise the window or open a link.
        let b = backend.clone();
        inbox.set_handler(Box::new(move |msg| b.handle_message(msg)));
    }
    let b = backend.clone();
    window
        .window()
        .on_close_requested(move || b.close_requested());
    // Not `window.run()`: hiding the window to the tray must not end the loop.
    // Only the GL renderers report frames reliably (Skia/Vulkan does not call
    // the rendering notifier; Vulkan is probed before selection instead).
    let watch = matches!(chosen, Some(Renderer::SkiaOpenGl | Renderer::FemtoVg));
    let no_frame = first_frame_watchdog(&window, watch);
    if let Some(r) = chosen {
        confirm_renderer(r.name(), index, std::rc::Rc::clone(&no_frame));
    }
    let looped = slint::run_event_loop_until_quit();
    backend.shutdown();
    // A renderer that never drew may also make the loop itself fail on the
    // way out; the missing frame is the error that triggers the fallback.
    if no_frame.get() {
        return Err(NoFirstFrame.into());
    }
    looped.context("running event loop")?;
    if chosen.is_some() {
        clear_renderer_pending();
    }
    Ok(())
}

/// Quits the event loop and sets the returned flag if the window has drawn
/// nothing after [`FIRST_FRAME_TIMEOUT`]. Inactive under `SLINT_BACKEND` and
/// for renderers that do not report frames (nothing to fall back to then).
fn first_frame_watchdog(window: &AppWindow, enabled: bool) -> std::rc::Rc<std::cell::Cell<bool>> {
    use std::cell::Cell;
    use std::rc::Rc;
    let no_frame = Rc::new(Cell::new(false));
    if !enabled {
        return no_frame;
    }
    let drew = Rc::new(Cell::new(false));
    let flag = Rc::clone(&drew);
    let watching = window
        .window()
        .set_rendering_notifier(move |state, _| {
            if matches!(state, slint::RenderingState::AfterRendering) {
                flag.set(true);
            }
        })
        .is_ok();
    if watching {
        let failed = Rc::clone(&no_frame);
        let weak = window.as_weak();
        slint::Timer::single_shot(FIRST_FRAME_TIMEOUT, move || {
            if !drew.get() {
                tracing::error!("no frame drawn since startup; trying the next renderer");
                failed.set(true);
                if let Some(w) = weak.upgrade() {
                    let _ = w.hide();
                }
                let _ = slint::quit_event_loop();
            }
        });
    }
    no_frame
}

fn wire(window: &AppWindow, backend: &Backend) {
    macro_rules! bind {
        ($on:ident, |$b:ident $(, $a:ident)*| $body:expr) => {{
            let $b = backend.clone();
            window.$on(move |$($a),*| $body);
        }};
    }
    bind!(on_start_login, |b| b.start_login());
    bind!(on_open_login_url, |b| b.open_login_url());
    bind!(on_logout, |b| b.logout());
    bind!(on_back, |b| b.back());
    bind!(on_forward, |b| b.forward());
    bind!(on_go, |b, key| b.go(&key));
    bind!(on_open_playlist, |b, id| b.open_playlist(&id));
    bind!(on_open_card, |b, kind, id| b.open_card(&kind, &id));
    bind!(on_play_card, |b, kind, id| b.play_card(&kind, &id));
    bind!(on_search, |b, q| b.search(&q));
    bind!(on_play_row, |b, i| b
        .play_row(usize::try_from(i).unwrap_or(0)));
    bind!(on_row_action, |b, i, a| b
        .row_action(usize::try_from(i).unwrap_or(0), &a));
    bind!(on_play_all, |b| b.play_all(false));
    bind!(on_shuffle_all, |b| b.play_all(true));
    bind!(on_hero_play, |b| b.hero_play(false));
    bind!(on_hero_shuffle, |b| b.hero_play(true));
    bind!(on_queue_play, |b, i| b
        .queue_play(usize::try_from(i).unwrap_or(0)));
    bind!(on_queue_remove, |b, i| b
        .queue_remove(usize::try_from(i).unwrap_or(0)));
    bind!(on_queue_clear, |b| b.queue_clear());
    bind!(on_lyric_seek, |b, i| b
        .lyric_seek(usize::try_from(i).unwrap_or(0)));
    bind!(on_toggle_favorite, |b| b.toggle_current_favorite());
    bind!(on_toggle_page_favorite, |b| b.toggle_page_favorite());
    bind!(on_toggle_hero_favorite, |b| b.toggle_hero_favorite());
    bind!(on_add_to_playlist, |b, t, u| b.add_to_playlist(t, &u));
    bind!(on_create_playlist, |b, t, n| b.create_playlist(t, &n));
    bind!(on_create_folder, |b, n| b.create_folder(&n));
    bind!(on_dialog_accepted, |b, k, t, x| b
        .dialog_accepted(&k, &t, &x));
    bind!(on_open_signal_path, |b| b.open_signal_path());
    bind!(on_open_miniplayer, |b| b.open_miniplayer());
    bind!(on_video_toggle, |b| b.video_toggle());
    bind!(on_video_seek, |b, f| b.video_seek(f));
    bind!(on_cycle_sort, |b| b.change_sort(false));
    bind!(on_flip_sort, |b| b.change_sort(true));
    bind!(on_video_close, |b| b.close_video());
    bind!(on_toggle_play, |b| b.toggle_play());
    bind!(on_next, |b| b.next());
    bind!(on_previous, |b| b.previous());
    bind!(on_toggle_shuffle, |b| b.toggle_shuffle());
    bind!(on_cycle_repeat, |b| b.cycle_repeat());
    bind!(on_toggle_mute, |b| b.toggle_mute());
    bind!(on_seek, |b, f| b.seek(f));
    bind!(on_seek_relative, |b, d| b.seek_relative(d));
    bind!(on_set_volume, |b, v| b.set_volume(v));

    let p = window.global::<ProfileState>();
    let b = backend.clone();
    p.on_save(move || b.save_profile());
    let b = backend.clone();
    p.on_pick_picture(move || b.pick_profile_picture());
    let b = backend.clone();
    p.on_remove_picture(move || b.remove_profile_picture());

    let g = window.global::<SettingsState>();
    let b = backend.clone();
    g.on_theme_preset(move |i| b.theme_preset(usize::try_from(i).unwrap_or(0)));
    let b = backend.clone();
    g.on_theme_color(move |t, c| b.theme_color(t, c, false));
    let b = backend.clone();
    g.on_theme_color_final(move |t, c| b.theme_color(t, c, true));
    let b = backend.clone();
    g.on_theme_hex(move |t, s| b.theme_hex(t, &s));
    let b = backend.clone();
    g.on_changed_bool(move |k, v| b.setting_bool(&k, v));
    let b = backend.clone();
    g.on_changed_int(move |k, v| b.setting_int(&k, v));
    let b = backend.clone();
    g.on_changed_str(move |k, v| b.setting_str(&k, &v));
    let b = backend.clone();
    g.on_action(move |a| b.setting_action(&a));
}

/// Slint fixes its platform once per process, so trying another renderer needs
/// a fresh process. The launch-time scrub removed the user's proxy variables
/// from this process; hand them back so the child scrubs from the same input.
fn respawn(next_index: usize, inbox: Option<&Inbox>) -> anyhow::Result<()> {
    let exe = std::env::current_exe().context("locating own executable")?;
    let mut child = std::process::Command::new(exe)
        .args(std::env::args_os().skip(1))
        .envs(slate_core::proxy::scrubbed_env().iter().cloned())
        .env(INDEX_ENV, next_index.to_string())
        .stdin(std::process::Stdio::piped())
        .spawn()
        .context("relaunching with a fallback renderer")?;
    // This process still owns the single-instance socket: pass what arrives
    // there on to the child, one message per line.
    match (inbox, child.stdin.take()) {
        (Some(inbox), Some(stdin)) => {
            let stdin = std::sync::Mutex::new(stdin);
            inbox.set_handler(Box::new(move |msg| {
                if let Ok(mut s) = stdin.lock() {
                    let _ = std::io::Write::write_all(&mut *s, format!("{msg}\n").as_bytes());
                }
            }));
        }
        (_, stdin) => drop(stdin),
    }
    let status = child.wait().context("waiting for the fallback renderer")?;
    std::process::exit(status.code().unwrap_or(1));
}

/// Messages from later launches, handed to whoever currently shows the UI:
/// this process's window, or after a renderer fallback the relaunched child.
/// Messages that arrive while nobody is attached wait (up to a few).
#[derive(Clone, Default)]
struct Inbox(std::sync::Arc<std::sync::Mutex<InboxState>>);

type MessageHandler = Box<dyn Fn(&str) + Send>;

#[derive(Default)]
struct InboxState {
    handler: Option<MessageHandler>,
    pending: Vec<String>,
}

impl Inbox {
    const MAX_PENDING: usize = 16;

    fn start(rx: std::sync::mpsc::Receiver<String>) -> Self {
        let inbox = Self::default();
        let feed = inbox.clone();
        let spawned = std::thread::Builder::new()
            .name("slate-links".into())
            .spawn(move || {
                for msg in rx {
                    feed.deliver(msg);
                }
            });
        if let Err(e) = spawned {
            tracing::warn!("link forwarding unavailable: {e}");
        }
        inbox
    }

    fn deliver(&self, msg: String) {
        let Ok(mut s) = self.0.lock() else { return };
        match &s.handler {
            Some(h) => h(&msg),
            None if s.pending.len() < Self::MAX_PENDING => s.pending.push(msg),
            None => {}
        }
    }

    fn set_handler(&self, handler: MessageHandler) {
        let Ok(mut s) = self.0.lock() else { return };
        for msg in std::mem::take(&mut s.pending) {
            handler(&msg);
        }
        s.handler = Some(handler);
    }

    fn detach(&self) {
        if let Ok(mut s) = self.0.lock() {
            s.handler = None;
        }
    }
}

/// A fallback child's incoming messages: lines its parent writes to stdin.
fn stdin_messages() -> Option<std::sync::mpsc::Receiver<String>> {
    use std::io::BufRead;
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::Builder::new()
        .name("slate-links-in".into())
        .spawn(move || {
            for line in std::io::stdin().lock().lines().map_while(Result::ok) {
                let msg = line.trim();
                if !msg.is_empty() && tx.send(msg.to_string()).is_err() {
                    break;
                }
            }
        })
        .ok()?;
    Some(rx)
}

/// Stderr always; plus a rotating file under the config dir when the
/// "write log files" preference is on. The returned guard flushes the file on drop.
fn init_tracing() -> Option<tracing_appender::non_blocking::WorkerGuard> {
    use tracing_subscriber::prelude::*;
    use tracing_subscriber::EnvFilter;

    let filter = EnvFilter::try_from_env("SLATE_LOG")
        .or_else(|_| EnvFilter::try_from_default_env())
        .unwrap_or_else(|_| EnvFilter::new("info"));

    let dir = slate_core::config_dir_for_env();
    let to_file = dir
        .as_ref()
        .is_some_and(|d| slate_core::logging::read_logging_preference(&d.join("logging.toggle")));
    let appender = dir.filter(|_| to_file).and_then(|d| {
        // The appender prunes old files on creation and complains if the folder is missing.
        let _ = std::fs::create_dir_all(d.join("logs"));
        tracing_appender::rolling::Builder::new()
            .rotation(tracing_appender::rolling::Rotation::DAILY)
            .filename_prefix("slate")
            .filename_suffix("log")
            .max_log_files(7)
            .build(d.join("logs"))
            .ok()
    });
    let (file_layer, guard) = match appender {
        Some(a) => {
            let (writer, guard) = tracing_appender::non_blocking(a);
            let layer = tracing_subscriber::fmt::layer()
                .with_ansi(false)
                .with_writer(writer);
            (Some(layer), Some(guard))
        }
        None => (None, None),
    };
    tracing_subscriber::registry()
        .with(filter)
        .with(tracing_subscriber::fmt::layer())
        .with(file_layer)
        .init();
    guard
}
